// Parceiros — abre o painel de parceiros do módulo Guerra Artoniana (Foundry v13).
// Escolha o parceiro, o nível e o herói: o poder "Parceiro: Nome" vai para a ficha com os bônus.
const api = game.modules.get("guerra-artoniana")?.active ? game.modules.get("guerra-artoniana").api : null;
if (api?.abrirParceiros) api.abrirParceiros();
else ui.notifications.warn("Ative o módulo Guerra Artoniana (versão 2.4 ou mais nova) para usar o painel de parceiros.");
